SELECT 
-- {% if reduced %}
countries.*
${SELECT_REDUCED}
--
-- {% else %}
countries.*
--	, countries.`country_code`
--	, countries.`country_name`
--	, countries.`continent`
--

--
-- {% endif %}
--
FROM `${SCHEMA}`.`countries` countries
--

--
WHERE ${PARAMS}
--
AND ${CONTEXT}
--
