-- [list of duplicated columns below]
-- id_sale [order_items,sales]
-- product_id [order_items,products]


SELECT 
-- {% if reduced %}
order_items.*
${REPLACE_ORDER_ITEMS_SELECT_REDUCED}
--
-- {% else %}
order_items.*
${REPLACE_ORDER_ITEMS_SELECT}
--
${REPLACE_SALES_JOIN(sales)}
${REPLACE_PRODUCTS_JOIN(products)}
--
-- {% endif %}
--
FROM `${SCHEMA}`.`order_items` order_items
--
LEFT JOIN `${SCHEMA}`.`sales` sales ON (order_items.`id_sale` = sales.`id_sale`)
LEFT JOIN `${SCHEMA}`.`products` products ON (order_items.`product_id` = products.`product_id`)
--
WHERE ${PARAMS}
--
AND ${CONTEXT}
--
LIMIT ${LIMIT}

