-- [list of duplicated columns below]
-- country_code [user_behaviour,countries]
-- user_id [user_behaviour,users]


SELECT 
-- {% if reduced %}
user_behaviour.*
${REPLACE_USER_BEHAVIOUR_SELECT_REDUCED}
--
-- {% else %}
user_behaviour.*
${REPLACE_USER_BEHAVIOUR_SELECT}
--
${REPLACE_COUNTRIES_JOIN(countries)}
${REPLACE_USERS_JOIN(users)}
--
-- {% endif %}
--
FROM `${SCHEMA}`.`user_behaviour` user_behaviour
--
LEFT JOIN `${SCHEMA}`.`countries` countries ON (user_behaviour.`country_code` = countries.`country_code`)
LEFT JOIN `${SCHEMA}`.`users` users ON (user_behaviour.`user_id` = users.`user_id`)
--
WHERE ${PARAMS}
--
AND ${CONTEXT}
--
LIMIT ${LIMIT}
